// Generated by scripts/generate-piece-theme-css.mjs; do not edit.
// Gzip of generated-piece-themes.css, inflated before first paint so the package does not
// also ship the drawings as a stylesheet.

export const PIECE_THEME_CSS_GZIP = "";

export async function pieceThemeCss(): Promise<string> {
  const binary = atob(PIECE_THEME_CSS_GZIP);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  return new Response(stream).text();
}
